#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    char **grid = (char **)malloc(N * sizeof(char *));
    for (int i = 0; i < N; i++) {
        grid[i] = (char *)malloc((M + 1) * sizeof(char));
        scanf("%s", grid[i]);
    }

    int *queue = (int *)malloc(N * M * sizeof(int));
    int head = 0, tail = 0;

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            if (grid[i][j] == 'o') {
                queue[tail++] = i * M + j;
            }
        }
    }

    while (head < tail) {
        int idx = queue[head++];
        int i = idx / M;
        int j = idx % M;

        // Water falls vertically down
        if (i + 1 < N && grid[i + 1][j] == '.') {
            grid[i + 1][j] = 'o';
            queue[tail++] = (i + 1) * M + j;
        }

        // Water spreads horizontally if there is a shelf below the current cell
        if (i + 1 < N && grid[i + 1][j] == '#') {
            if (j > 0 && grid[i][j - 1] == '.') {
                grid[i][j - 1] = 'o';
                queue[tail++] = i * M + (j - 1);
            }
            if (j + 1 < M && grid[i][j + 1] == '.') {
                grid[i][j + 1] = 'o';
                queue[tail++] = i * M + (j + 1);
            }
        }
    }

    for (int i = 0; i < N; i++) {
        printf("%s\n", grid[i]);
    }

    for (int i = 0; i < N; i++) {
        free(grid[i]);
    }
    free(grid);
    free(queue);

    return 0;
}
